import{_ as e}from"./chunks/pm02d_hero.B7krLowi.js";import{_ as o}from"./chunks/pm02d_pinout.R-AJXYSl.js";import{_ as r,c as a,al as l,o as i}from"./chunks/framework.D3pXwl8O.js";const f=JSON.parse('{"title":"Holybro PM02D Енергогенератор","description":"","frontmatter":{},"headers":[],"relativePath":"uk/power_module/holybro_pm02d.md","filePath":"uk/power_module/holybro_pm02d.md"}'),n={name:"uk/power_module/holybro_pm02d.md"};function s(d,t,h,p,u,c){return i(),a("div",null,t[0]||(t[0]=[l('<h1 id="holybro-pm02d-енергогенератор" tabindex="-1">Holybro PM02D Енергогенератор <a class="header-anchor" href="#holybro-pm02d-енергогенератор" aria-label="Permalink to &quot;Holybro PM02D Енергогенератор&quot;">​</a></h1><p>The Holybro PM02D digital power module provides regulated power to flight controller and power distribution board, and sends information to the autopilot about battery voltage and current supplied to the flight controller and the motors.</p><p>Плата живлення підключається за допомогою протоколу I2C. It is designed for flight controllers based on the Pixhawk FMUv5X and FMUv6X open standard, including the <a href="./../flight_controller/pixhawk5x.html">Pixhawk 5X</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The PM is <strong>NOT</strong> compatible with flight controllers that require an analog power module, including: <a href="./../flight_controller/pixhawk4.html">Pixhawk 4</a>, <a href="./../flight_controller/durandal.html">Durandal</a>, <a href="./../flight_controller/holybro_pix32_v5.html">Pix32 v5</a>, etc.</p></div><p><img src="'+e+'" alt="PM02D"></p><h2 id="характеристики" tabindex="-1">Характеристики <a class="header-anchor" href="#характеристики" aria-label="Permalink to &quot;Характеристики&quot;">​</a></h2><ul><li><strong>Max input voltage</strong>: 36V</li><li><strong>Rated current</strong>: 60A</li><li><strong>Max current</strong>: 120A (&lt;60S)</li><li><strong>Max current sensing</strong>: 164A</li><li><strong>Battery supported</strong>: up to 6S battery</li><li><strong>Communication protocol</strong>: I2C</li><li><strong>Switching regulator outputs</strong>: 5.2V and 3A max</li><li><strong>Weight</strong>: 20g</li><li><strong>IC Used</strong>: TI INA228</li></ul><h2 id="вміст-набору" tabindex="-1">Вміст набору <a class="header-anchor" href="#вміст-набору" aria-label="Permalink to &quot;Вміст набору&quot;">​</a></h2><ul><li>PM02D дошка з коннекторами XT60</li><li>6pin 2.00мм інтервал CLIK-Mate кабель до протиживлення контролера</li></ul><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><p><a href="https://holybro.com/products/pm02d-power-module" target="_blank" rel="noreferrer">Order from Holybro Store</a></p><h2 id="проведення-підключення" tabindex="-1">Проведення/Підключення <a class="header-anchor" href="#проведення-підключення" aria-label="Permalink to &quot;Проведення/Підключення&quot;">​</a></h2><p><img src="'+o+'" alt="pm02d_pinout"></p><p>Additional wiring and connection information can be found in: <a href="./../assembly/quick_start_pixhawk5x.html">Holybro Pixhawk 5x Wiring Quick Start</a>.</p><h2 id="конфігурація-px4" tabindex="-1">Конфігурація PX4 <a class="header-anchor" href="#конфігурація-px4" aria-label="Permalink to &quot;Конфігурація PX4&quot;">​</a></h2><p>Enable parameter <a href="./../advanced_config/parameter_reference.html#SENS_EN_INA228">SENS_EN_INA228</a></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>There is an out-of-production low voltage version (6S) of this module with the same name, which uses the TI INA226 IC. For this module you must instead enable parameter <a href="./../advanced_config/parameter_reference.html#SENS_EN_INA226">SENS_EN_INA226</a>.</p></div><p>Note that the current divider and voltage divider should not be set in the <a href="./../config/battery.html">Battery Configuration</a> (the default values are accurate within 5%).</p><h2 id="дивіться-також" tabindex="-1">Дивіться також <a class="header-anchor" href="#дивіться-також" aria-label="Permalink to &quot;Дивіться також&quot;">​</a></h2><ul><li><a href="https://docs.holybro.com/power-module-and-pdb/power-module/digital-power-module-pm-setup#px4-setup" target="_blank" rel="noreferrer">Digital Power Module (PM) Setup</a> (Manufacturer guide)</li></ul>',20)]))}const b=r(n,[["render",s]]);export{f as __pageData,b as default};
